            ovs=[o for o in out if o['cols']&set(range(c0,max(c1)+1))]
            if any(True for _ in [False]): pass
            # overlap with any previously placed in this band
            ov=False
            for o in out:
                if o['cols'].intersection(set(range(min(c0)+1,max(c1)-1))) : ov=True; break
            start_r = r0 if not ov else prev_r+h-1
            out.append({'col':col_,'cells':[(r-start_r+r0,c) for r,c in cells],'r0':start_r})
            prev_r=max(prev_r,start_r+h-1)
        return out
    tops=place(top,0); bots=place(bot,H-1)
    res=[[0]*W for _ in range(H)]
    for t in tops:
