        inter={(i,j) for i in range(r0+1,r1) for j in range(c0+1,c1)} & set(cells)
        closed = len(inter)==0
        h=r1-r0+1
        rel=[(r-r0,c) for r,c in cells]
        items.append(dict(col_=col_,h=h,w=c1-c0+1,rel=sorted(rel),orig=sorted(cells),
                          closed=closed,first_r=r0))
    def band(itms, dir_):
        # dir_: 'top' -> grow downward from 0; 'bottom' -> grow upward from H-1
        pos=[]  # list of (start_row, h, col_set)
        for it in itms:
            cset={c for _,c in it['rel']}
            s = 0 if dir_=='top' else H-it['h']
            while True:
                ok=True
                for (ps,hp,cs2) in pos:
                    if dir_=='top':
                        if cs2 & cset and max(ps+h for ps in [ps]-[ps]+[ps])!=ps:
                            pass
                    if cs2 & cset:
                        fr=it['first_r']
                        if dir_=='top':
                            # footprint of placed: rows ps..ps+hp-1
                            if (ps <= fr+it['h']-1) and (fr <= ps):
                                ok=False; break
                        else:
                            pass
                if ok:
                    if dir_=='top': res=s; else: res=H-1-(s+it['h'])+...
                break
        return pos
    # clearer: place with collision check along rows within column overlap
    top=[]; bot=[]
    for it in items:
        top.append(it) if it['closed'] else bot.append(it)
    def settle(items, anchor):
        res=[]
        placed={}  # col -> list of (start,h)
        for it in items:
            cset={c for _,c in it['rel']}
            best=start=None
            if anchor==0:
                cand=[]
                for (ps,hp,_) in res:
                    for (r,c) in it['rel']:
                        col=c
                        if col in any(cs2 for _,cs2 in placed.items()): pass
                # find tightest fit: smallest s>=0 such that no placed item in same columns overlaps
                s=0
                while any((cs2 & cset) and (s<=ps+hp-1 and ps<=s+it['h']-1) for ps,hp,cs2 in [(p[0],p[1],None) for p in []]): pass
                best=s
            res.append((best,it['h'],cset))
        return res
    tops=settle(top,0); bots=settle(bot,1)

